function obj = loadBehavObjs(meta)
for i = 1:numel(meta)
    dat = load(meta(i).datapth);
    if ~isfield(dat.obj,'meta')
        dat.obj.meta = 'assigning to avoid dissimilar struct error';
    end
    dat.obj.vidshift = findVideoOffset(dat.obj);
    obj(i) = dat.obj;
    clear dat
end
