import os, re, h5py, numpy as np

def scalar(ds):
    arr = ds[()]
    if isinstance(arr, np.ndarray):
        if arr.size == 1:
            return arr.reshape(-1)[0].item()
    return arr

def ntrials_and_clu(path):
    with h5py.File(path, 'r') as f:
        obj = f['obj']
        ntrials = int(scalar(f[obj['bp']['Ntrials'][0,0]]))
        has_clu = 'clu' in obj
        n_units = 0
        n_probes = 0
        if has_clu:
            clu_refs = obj['clu']
            n_probes = clu_refs.shape[1] if clu_refs.ndim == 2 else clu_refs.shape[0]
            refs = clu_refs[0] if clu_refs.ndim == 2 else clu_refs
            for ref in refs:
                target = f[ref]
                if isinstance(target, h5py.Group):
                    n_units += target.shape[0] if hasattr(target, 'shape') and target.shape else len(target)
                else:
                    n_units += target.shape[0]
        return ntrials, has_clu, n_units, n_probes

