python3 - <<'PY'
import pathlib, re, os, h5py, numpy as np, scipy.io as sio
from scipy.io.matlab import mat_struct

base=pathlib.Path('/app/code/DataLoadingScripts/Recording and video')
block_pat = re.compile(r"^\s*meta\(end\+1\).*?^\s*meta\(end\)\.anm = '([^']+)';.*?^\s*meta\(end\)\.date = '([^']+)';.*?^\s*meta\(end\)\.probe = ([0-9]+);", re.M|re.S)

sessions=[]
for path in sorted(base.glob('load*_ALMVideo.m')):
    text=path.read_text()
    for m in block_pat.finditer(text):
        anm,date,probe=m.groups()
        sessions.append((path.name, anm, date, int(probe)))
print('parsed sessions', len(sessions))
print('first 10', sessions[:10])

# classify by figure-script usage
fixed_animals={'JEB6','JEB7','EKH1','EKH3','JGR2','JGR3','JEB13','JEB14','JEB15','JEB19'}
context_animals={'JEB6','JEB7','EKH1','EKH3','JGR2','JGR3','JEB19'}
random_animals={'JEB11','JEB12','JEB23','JEB24'}
print('fixed sessions', sum(anm in fixed_animals for _,anm,_,_ in sessions))
print('context sessions', sum(anm in context_animals for _,anm,_,_ in sessions))
print('random sessions', sum(anm in random_animals for _,anm,_,_ in sessions))

# counts of raw units on selected ALM probes

def count_units_v73(path, probe_sel):
    with h5py.File(path,'r') as f:
        obj=f['obj']
        if 'clu' not in obj:
            return 0
        refs=obj['clu'][()].reshape(-1)
        idx=probe_sel-1
        if idx >= len(refs):
            return 0
        tgt=f[refs[idx]]
        if isinstance(tgt, h5py.Group) and 'quality' in tgt:
            return int(tgt['quality'].shape[0])
        return 0

def count_units_v5(path, probe_sel):
    obj=sio.loadmat(path, struct_as_record=False, squeeze_me=True)['obj']
    clu=getattr(obj,'clu',None)
    if isinstance(clu, np.ndarray):
        return int(clu.size)
    elif isinstance(clu, mat_struct):
        return 1
    return 0

from collections import defaultdict
counts=defaultdict(int)
missing=[]
for manifest, anm, date, probe in sessions:
    cohort_candidates=[
        f'/app/data/Ephys_Behavior/data_structure_{anm}_{date}.mat',
        f'/app/data/RandomizedDelay_Ephys_Behavior/data_structure_{anm}_{date}.mat',
    ]
    path=None
    for cand in cohort_candidates:
        if os.path.exists(cand):
            path=cand
            break
    if path is None:
        missing.append((anm,date,manifest))
        continue
    try:
        n=count_units_v73(path, probe)
    except OSError:
